// Main-owned integration check of the actual renderer against IDs from the actual page.
const fs = require('node:fs');
const vm = require('node:vm');
const assert = require('node:assert/strict');
const path = require('node:path');
const root = process.argv[2];
const js = fs.readFileSync(path.join(root, 'serve/web/app.js'), 'utf8');
const html = fs.readFileSync(path.join(root, 'serve/web/index.html'), 'utf8');
const ids = new Set([...html.matchAll(/\bid="([^"]+)"/g)].map(m => m[1]));
const elements = new Map();
const document = {getElementById(id) {
  assert(ids.has(id), `renderer ID missing from page: ${id}`);
  if (!elements.has(id)) elements.set(id, {hidden: false, textContent: '', innerHTML: '', style: {}});
  return elements.get(id);
}};
const context = vm.createContext({document});
const helpers = js.split('\n').filter(line => /^(const \$ =|const esc =|const fmt =|const gb =)/.test(line)).join('\n');
const renderer = js.slice(js.indexOf('function since(t)'), js.indexOf('function renderTotals('));
const facts = js.slice(js.indexOf('function facts(el, rows)'), js.indexOf('// INFO cvec='));
assert(renderer.startsWith('function since(t)') && facts.startsWith('function facts(el, rows)'));
vm.runInContext(helpers + '\n' + facts + '\n' + renderer, context, {timeout: 1000});
function render(value) {
  context.value = value;
  vm.runInContext('renderConvCache(value)', context, {timeout: 1000});
}
render(null);
assert.equal(document.getElementById('cc-card').hidden, true);
const base = {enabled: true, available: true, complete: true, parked: 1, slots: 4, bytes: 104857600,
  budget_mib: 8192, requests: 3, requests_reused: 2, reused_tokens: 900, prompt_tokens: 1000,
  last_prompt: 400, last_reused: 300, parks: 2, restores: 1, evictions: 0, last_event: 'restored',
  last_tokens: 4000, last_at: Date.now() / 1000};
render(base);
assert.equal(document.getElementById('cc-card').hidden, false);
assert.equal(document.getElementById('cc-bars').hidden, false);
assert.equal(document.getElementById('cc-slots-bar').style.width, '25%');
assert.match(document.getElementById('cc-facts').innerHTML, /Restored/);
render({...base, available: false});
assert.equal(document.getElementById('cc-bars').hidden, true);
assert.match(document.getElementById('cc-note').textContent, /unavailable/);
render({...base, bytes: null, complete: false});
assert.match(document.getElementById('cc-mem-text').textContent, /Unknown/);
assert.match(document.getElementById('cc-note').textContent, /incomplete/);
render({...base, enabled: false});
assert.equal(document.getElementById('cc-bars').hidden, true);
render({...base, parked: 8});
assert.equal(document.getElementById('cc-slots-bar').style.width, '100%');
console.log(JSON.stringify({passed: true, renderer: 'actual source functions', page: 'actual DOM IDs',
  cases: ['older server', 'enabled', 'no log', 'unknown bytes', 'incomplete history', 'disabled', 'bar clamp'],
  limitation: 'DOM bindings and renderer behavior; no browser layout or live native cache qualification'}));
